CREATE OR REPLACE FUNCTION public.dispatch_job_refresh(p_url text, p_secret text, p_force boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; queued jsonb='[]'::jsonb; req bigint; BEGIN IF p_url NOT IN ('https://www.dibyamishra.co.in/api/public/cron/jobs-sync','https://dibyamishra.co.in/api/public/cron/jobs-sync','https://dibyamishrablog.lovable.app/api/public/cron/jobs-sync','https://project--afb27601-9db8-4f5f-bd9a-50ae5eee7ddc.lovable.app/api/public/cron/jobs-sync','https://project--afb27601-9db8-4f5f-bd9a-50ae5eee7ddc-dev.lovable.app/api/public/cron/jobs-sync') OR length(p_secret)<16 THEN RAISE EXCEPTION 'Invalid refresh configuration'; END IF; FOR s IN SELECT slug FROM public.job_sources WHERE active AND status='connected' AND (locked_until IS NULL OR locked_until<now()) AND (retry_after IS NULL OR retry_after<=now()) AND (p_force OR last_synced_at IS NULL OR last_synced_at+make_interval(mins=>poll_minutes)<=now()) ORDER BY id LOOP SELECT net.http_post(url:=p_url,headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||p_secret),body:=jsonb_build_object('mode','source','sourceSlug',s.slug,'force',p_force),timeout_milliseconds:=300000) INTO req; queued=queued||jsonb_build_array(jsonb_build_object('source',s.slug,'status','queued')); END LOOP; PERFORM net.http_post(url:=p_url,headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||p_secret),body:='{"mode":"maintenance"}'::jsonb,timeout_milliseconds:=300000); RETURN queued; END $$;
REVOKE ALL ON FUNCTION public.dispatch_job_refresh(text,text,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.dispatch_job_refresh(text,text,boolean) TO service_role;